frontalRepeat.script:
import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {cpus} from 'node:os';
import {boundedGripInterval} from '../../scripts/diag/physics/grip-force-bounded.js';
import {sourceVersion} from '../../scripts/source-version.js';
const fixtures=JSON.parse(readFileSync('config/grip-bounded-reference.json','utf8')),
  c=fixtures.cases.find((v:any)=>v.id==='patch-0-3-0-3001-1-acquired'),input=structuredClone(c.input),
  modes=['adaptive','eliminated','capped'] as const,
  samples=new Map(modes.map(m=>[m,[] as Array<{milliseconds:number,result:ReturnType<typeof boundedGripInterval>}>]));
function physical(r:ReturnType<typeof boundedGripInterval>) {
 const {integration,stageStatistics,eventMaxBracket,...state}=r;return state;
}
assert.deepEqual(physical(boundedGripInterval(input,'capped')),physical(boundedGripInterval(input,'eliminated')));
for(let k=0;k<30;k++)for(const mode of modes)boundedGripInterval(input,mode);
for(let k=0;k<21;k++)for(let j=0;j<modes.length;j++) {
 const mode=modes[(j+k)%modes.length],start=performance.now(),result=boundedGripInterval(input,mode);
 samples.get(mode)!.push({milliseconds:performance.now()-start,result});
}
const rows=modes.map(mode=>{
 const reps=samples.get(mode)!,times=reps.map(s=>s.milliseconds),sorted=[...times].sort((a,b)=>a-b);
 assert(reps.every(s=>JSON.stringify(s.result)===JSON.stringify(reps[0].result)));assert.deepEqual(input,c.input);
 return {mode,milliseconds:{median:sorted[10],p95:sorted[19],maximum:sorted[20]},samples:times,
   evaluations:reps[0].result.evaluations,partitions:reps[0].result.partitions};
});
const hash=(p:string)=>createHash('sha256').update(readFileSync(p)).digest('hex');
writeFileSync('out/grip-cap/frontal-cost.json',JSON.stringify({commit:execFileSync('git',['rev-parse','HEAD'],{encoding:'utf8'}).trim(),
 source:sourceVersion(),node:process.version,cpu:cpus()[0].model,baseline:fixtures.baseline,
 flags:Object.fromEntries(Object.keys(fixtures.flags).map(k=>[k,process.env[k]??null])),input,
 hashes:Object.fromEntries(['out/grip-cap/frontal-cost.ts','config/grip-bounded-reference.json',
 'scripts/diag/physics/grip-force-bounded.ts','scripts/diag/physics/grip-passive-stages.ts'].map(p=>[p,hash(p)])),
 protocol:{serial:true,freshProcess:true,warmups:30,repetitions:21,rotatingOrder:true,observersOrProfilers:false,
 reason:'Initial unchanged frontal control had p95 >5ms and spikes across all methods; check sustained isolated cost before wider integration.'},
 physicalEndpointsExactBetweenEliminatedAndCapped:true,rows},null,2)+'\n');
